271	#[cfg(not(feature = "hosted"))]
272	struct BumpAllocator {
273	    next: AtomicUsize,
274	    end:  AtomicUsize,
275	}
276	
277	#[cfg(not(feature = "hosted"))]
278	impl BumpAllocator {
279	    const fn new() -> Self {
280	        Self { next: AtomicUsize::new(0), end: AtomicUsize::new(0) }
281	    }
282	    fn init(&self, start: usize, size: usize) {
283	        self.next.store(start, Ordering::Relaxed);
284	        self.end.store(start + size, Ordering::Relaxed);
285	    }
286	}
