288	#[cfg(not(feature = "hosted"))]
289	unsafe impl core::alloc::GlobalAlloc for BumpAllocator {
290	    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
291	        let align = layout.align();
292	        let size  = layout.size();
293	        // A zero-size request must never fail. With the heap nearly full the
294	        // alignment round-up alone can push past `end`, and returning null for a
295	        // zero-byte allocation surfaced as "memory allocation of 0 bytes failed"
296	        // — a panic that named a size nobody had asked for. Hand back a dangling
297	        // but correctly aligned pointer, which is what a zero-size allocation is.
298	        if size == 0 {
299	            return align as *mut u8;
300	        }
301	        loop {
302	            let cur     = self.next.load(Ordering::Relaxed);
303	            let aligned = (cur + align - 1) & !(align - 1);
304	            let new     = aligned + size;
305	            // Null here reaches `alloc_error` below, which reports the real
306	            // layout. Nothing is printed at this point so a caller that
307	            // handles the null itself is not made to look like a crash.
308	            if new > self.end.load(Ordering::Relaxed) { return core::ptr::null_mut(); }
309	            if self.next.compare_exchange_weak(
310	                cur, new, Ordering::Relaxed, Ordering::Relaxed,
311	            ).is_ok() {
312	                return aligned as *mut u8;
313	            }
314	        }
315	    }
316	    unsafe fn dealloc(&self, ptr: *mut u8, layout: Layout) {
317	        // LIFO reclaim: if this block is the most recent allocation, roll the
318	        // bump pointer back. Catches the transient Vecs of a forward pass.
319	        let end = ptr as usize + layout.size();
320	        let _ = self.next.compare_exchange(
321	            end, ptr as usize, Ordering::Relaxed, Ordering::Relaxed,
322	        );
323	    }
324	}
