330	/// Mark/reset scope for transient heavy work (the vita turn): everything
331	/// allocated after `heap_mark()` is reclaimed by `heap_reset(mark)`. Only
332	/// sound when nothing allocated inside the scope outlives it.
333	#[cfg(not(feature = "hosted"))]
334	pub fn heap_mark() -> usize {
335	    ALLOCATOR.next.load(Ordering::Relaxed)
336	}
337	#[cfg(not(feature = "hosted"))]
338	pub fn heap_reset(mark: usize) {
339	    ALLOCATOR.next.store(mark, Ordering::Relaxed);
340	}
341	/// Bytes currently handed out, and the arena total. A bump allocator that has
342	/// run out returns null and the allocation error path takes the kernel down
343	/// without a message, so anything heavy should report this rather than let
344	/// exhaustion look like a hang.
345	#[cfg(not(feature = "hosted"))]
346	pub fn heap_used() -> (usize, usize) {
347	    let next = ALLOCATOR.next.load(Ordering::Relaxed);
348	    let end = ALLOCATOR.end.load(Ordering::Relaxed);
349	    let start = unsafe { core::ptr::addr_of!(HEAP_STORAGE.0) as usize };
350	    (next.saturating_sub(start), end.saturating_sub(start))
351	}
