392	// ── Hosted runtime ───────────────────────────────────────────────────
393	// On a host the OS supplies what the bare-metal half builds by hand: an
394	// allocator, a stack, a panic path, and an entry point. So there is nothing to
395	// port here, only to step aside for.
396	
397	// The host allocator is wrapped so its use is measured rather than assumed.
398	// An earlier version returned a constant 48 MB here on the grounds that it kept
399	// size decisions identical across builds. That is a hardcode standing in for a
400	// measurement, which is the thing this project exists to not do: every value
401	// should be computed. `used` below is now real, counted allocation by
402	// allocation, and works anywhere Rust runs.
403	#[cfg(feature = "hosted")]
404	mod hosted_heap {
405	    use core::sync::atomic::{AtomicUsize, Ordering};
406	    use std::alloc::{GlobalAlloc, Layout, System};
407	
408	    pub static USED: AtomicUsize = AtomicUsize::new(0);
409	
410	    /// Not a measurement and not pretending to be. A host has no fixed arena,
411	    /// so there is no total to read; this is a declared ceiling that the
412	    /// heavy-job guards compare against, defaulting to the bare-metal arena so
413	    /// the two builds refuse the same work. Settable at runtime.
414	    pub static BUDGET: AtomicUsize = AtomicUsize::new(48 * 1024 * 1024);
415	
416	    pub struct Counting;
417	
418	    unsafe impl GlobalAlloc for Counting {
419	        unsafe fn alloc(&self, l: Layout) -> *mut u8 {
420	            let p = System.alloc(l);
421	            if !p.is_null() { USED.fetch_add(l.size(), Ordering::Relaxed); }
422	            p
423	        }
424	        unsafe fn dealloc(&self, p: *mut u8, l: Layout) {
425	            System.dealloc(p, l);
426	            USED.fetch_sub(l.size(), Ordering::Relaxed);
427	        }
428	    }
429	}
