601	    sprintln!("{}[boot]{} {} total programs (I–XXIX): 12 canonical + {} continuous + {} novel + {} shunted", style::muted(), style::reset(),
602	        canonical_count() + continuous_count() + novel_count() + shunted_count(),
603	        continuous_count(), novel_count(), shunted_count());
604	    sprintln!();
605	
606	    print_banner();
