626	        core::arch::asm!(
627	            "out dx, eax",
628	            in("dx") 0xf4_u16,
629	            in("eax") 0x10_u32,
630	            options(nomem, nostack, preserves_flags)
631	        );
632	    }
633	    #[cfg(not(feature = "hosted"))]
634	    loop { unsafe { core::arch::asm!("hlt", options(nostack, nomem, preserves_flags)); } }
