642	    // reader has no context yet, so it leads with the object and not the
643	    // feature list.
644	    sprintln!();
645	    sprintln!("   {}⊙{}   {}G-mOMonadOS{}", style::glyph(), style::reset(),
646	              style::heading(), style::reset());
647	    #[cfg(not(feature = "hosted"))]
648	    sprintln!("   {}the self-imscribing bare-metal kernel{}", style::muted(), style::reset());
649	    #[cfg(feature = "hosted")]
650	    sprintln!("   {}GPU-native build, mOMonadOS ported to run via CUDA{}", style::muted(), style::reset());
651	    sprintln!("   {}μ∘δ = id{}", style::accent(), style::reset());
652	    sprintln!();
653	    sprintln!("   {}Frobenius core · Belnap FOUR · crystal FS · graph execution{}",
654	              style::muted(), style::reset());
655	    sprintln!();
656	    sprintln!("   {}help{} for commands, {}?{} for the menu, Tab completes.",
657	              style::key(), style::reset(), style::key(), style::reset());
658	    sprintln!();
659	}
660	
661	// ─── Panic ────────────────────────────────────────────────────
662	
663	#[cfg(not(feature = "hosted"))]
664	#[panic_handler]
665	fn panic(info: &PanicInfo) -> ! {
666	    serial::write_str("\n[PANIC] ");
667	    sprint!("{}", info.message());
668	    sprintln!();
669	    loop { unsafe { core::arch::asm!("hlt", options(nostack, nomem, preserves_flags)); } }
670	}
671	
672	/// Report heap exhaustion ourselves.
673	///
674	/// The default handler reaches the panic through `__rust_alloc_error_handler`,
675	/// an internal symbol that takes the size and align as loose integers. Under
676	/// this build — `build-std` with fat LTO — that call arrives with a size of
677	/// zero however large the failed request was: an allocation of 1264 bytes
678	/// against 552 free reported itself as "memory allocation of 0 bytes failed",
679	/// which sent every reader hunting for a zero-size bug that does not exist.
680	///
681	/// Taking the `Layout` here reads it directly instead of through that symbol,
682	/// and the writes below never allocate, which matters when the reason we are
683	/// here is that allocation just failed.
684	#[cfg(not(feature = "hosted"))]
685	#[alloc_error_handler]
686	fn alloc_error(layout: Layout) -> ! {
687	    let (used, total) = heap_used();
688	    serial::write_str("\n[PANIC] heap exhausted — wanted ");
689	    serial::write_dec(layout.size());
690	    serial::write_str(" bytes (align ");
691	    serial::write_dec(layout.align());
692	    serial::write_str("), ");
693	    serial::write_dec(total.saturating_sub(used));
694	    serial::write_str(" free of ");
695	    serial::write_dec(total);
696	    serial::write_str("\n");
697	    loop { unsafe { core::arch::asm!("hlt", options(nostack, nomem, preserves_flags)); } }
698	}
