75	    pub bits: u8,
76	    /// Parsed from the module's own `; sym NAME 0xADDR` lines, so a saved
77	    /// `.imasm` file resolves a symbol name without a second read of the
78	    /// original binary.
79	    pub symbols: BTreeMap<String, u64>,
80	    /// Anonymous-mmap and brk cursors: fresh regions far from any loaded code
81	    /// or data, since `mem` is a sparse map and reads of never-written bytes
82	    /// already come back zero — a freshly "mapped" page needs no zeroing.
83	    mmap_next: u64,
84	    brk_cur: u64,
85	    /// Real file and console I/O, when a hosted caller supplies one.
86	    host: Option<Box<dyn Host>>,
87	}
88	
89	impl Machine {
90	    pub fn new(module: &str) -> Machine {
91	        let mut m = Machine {
92	            code: BTreeMap::new(), addrs: Vec::new(), next_of: BTreeMap::new(), entry: 0,
93	            reg: BTreeMap::new(), mem: BTreeMap::new(), flags: (0,0,1), kind: "cmp".into(), steps: 0, bits: 64,
94	            symbols: BTreeMap::new(),
95	            mmap_next: 0x0003_0000_0000, brk_cur: 0x0002_0000_0000, host: None,
96	        };
97	        for r in ["rax","rcx","rdx","rbx","rsp","rbp","rsi","rdi","r8","r9","r10","r11","r12","r13","r14","r15","rip"] {
98	            m.reg.insert(r.into(), 0);
99	        }
100	        for k in 0..16 { m.reg.insert(format!("xmm{}", k), 0); }
101	        m.reg.insert("rsp".into(), 0x7FFF_0000);
102	        m.parse(module);
103	        m
104	    }
105	
106	    fn parse(&mut self, text: &str) {
107	        let mut addr: Option<u64> = None;
108	        for line in text.lines() {
109	            if let Some(rest) = line.strip_prefix(';') {
110	                let t = rest.trim();
111	                if let Some(e) = t.strip_prefix("entry ") {
112	                    if let Ok(v) = u64::from_str_radix(e.trim().trim_start_matches("0x"), 16) { self.entry = v; }
113	                } else if let Some(b) = t.strip_prefix("bits ") {
114	                    if let Ok(v) = b.trim().parse::<u8>() { self.bits = v; }
115	                } else if let Some(s) = t.strip_prefix("sym ") {
116	                    let mut it = s.rsplitn(2, ' ');
117	                    if let (Some(addr_s), Some(name)) = (it.next(), it.next()) {
118	                        if let Ok(v) = u64::from_str_radix(addr_s.trim().trim_start_matches("0x"), 16) {
119	                            self.symbols.insert(name.to_string(), v);
120	                        }
121	                    }
122	                }
123	            } else if let Some(rest) = line.strip_prefix('=') {
124	                let mut it = rest.splitn(2, '\t');
125	                if let (Some(at), Some(blob)) = (it.next(), it.next()) {
126	                    if let Ok(a) = u64::from_str_radix(at.trim().trim_start_matches("0x"), 16) {
127	                        let bytes = hexbytes(blob);
128	                        for (k, b) in bytes.iter().enumerate() { if *b != 0 { self.mem.insert(a + k as u64, *b); } }
129	                    }
130	                }
131	            } else if let Some(rest) = line.strip_prefix('@') {
132	                if let Ok(a) = u64::from_str_radix(rest.trim().trim_start_matches("0x"), 16) {
133	                    addr = Some(a); self.code.entry(a).or_default();
134	                }
135	            } else if !line.is_empty() {
136	                if let Some(a) = addr {
137	                    let mut parts = line.split('\t');
138	                    if let Some(g) = parts.next() {
139	                        let glyph = g.chars().next().unwrap_or('?');
140	                        let fields: Vec<String> = parts.map(|s| s.to_string()).collect();
141	                        self.code.get_mut(&a).unwrap().push((glyph, fields));
142	                    }
143	                }
144	            }
145	        }
146	        self.addrs = self.code.keys().copied().collect();
147	        for w in self.addrs.windows(2) { self.next_of.insert(w[0], w[1]); }
148	    }
149	
150	    // ── slots ──
151	    fn get_reg(&self, name: &str) -> u128 {
152	        let (base, size, off) = reg_info(name);
153	        (self.reg[base] >> (off as u32 * 8)) & mask(size)
154	    }
155	    fn set_reg(&mut self, name: &str, val: u128) {
156	        let (base, size, off) = reg_info(name);
157	        let cur = self.reg.get(base).copied().unwrap_or(0);
158	        let nv = match size {
159	            8 => val & mask(8),
160	            4 => val & mask(4),           // 32-bit writes zero the top
161	            16 => val & mask(16),
162	            _ => { let m = mask(size) << (off as u32 * 8); (cur & !m) | ((val << (off as u32 * 8)) & m) }
163	        };
164	        self.reg.insert(base.to_string(), nv);
165	    }
166	    fn load(&self, addr: u64, size: u8) -> u128 {
167	        let mut v = 0u128;
168	        for k in 0..size as u64 { v |= (*self.mem.get(&(addr + k)).unwrap_or(&0) as u128) << (8 * k); }
169	        v
170	    }
171	    fn store(&mut self, addr: u64, val: u128, size: u8) {
172	        let v = val & mask(size);
173	        for k in 0..size as u64 { self.mem.insert(addr + k, ((v >> (8*k)) & 0xFF) as u8); }
174	    }
175	    fn ea(&self, field: &str) -> (u64, u8) {
176	        // m:base:index:scale:disp:size
177	        let parts: Vec<&str> = field.split(':').collect();
178	        let base = parts[1]; let index = parts[2]; let scale = parts[3];
179	        let disp = parts[4]; let size: u8 = parts[5].parse().unwrap_or(8);
180	        let mut a: i128 = if !base.is_empty() { self.get_reg(base) as i128 } else { 0 };
181	        if !index.is_empty() { a += self.get_reg(index) as i128 * scale.parse::<i128>().unwrap_or(1); }
182	        a += parse_imm(disp);
183	        ((a as u128 & mask(8)) as u64, size)
184	    }
185	    fn read(&self, field: &str, size_hint: u8) -> (u128, u8) {
