1	//! The module format: a word in the twelve, and the executable payload each
2	//! glyph carries. Ported from imasm_module.py. The glyph is the opcode (which of
3	//! the twelve axes the instruction is); the payload is normalised operands the
4	//! machine reads without ever parsing assembly.
5	//!
6	//! ```text
7	//! GLYPH \t field \t field ...      with  r:reg  i:imm  m:base:index:scale:disp:size
8	//! ```
9	
10	use alloc::string::{String, ToString};
11	use alloc::vec::Vec;
12	use alloc::collections::{BTreeMap, BTreeSet};
13	use alloc::format;
14	
15	use crate::x86::{self, Op};
16	use crate::vox_decode;
17	use crate::loader;
18	
19	fn bits_of(arch: &str) -> u8 { if arch == "x86-32" { 32 } else { 64 } }
20	
21	const ENTRY: char = '⊢'; const TERM: char = '⊣'; const SPLIT: char = '∈'; const FUSE: char = '∋';
22	const CALL: char = '≻'; const XFER: char = '≺'; const INDIRECT: char = '⊙'; const COMMIT: char = '⊡';
23	const LINK: char = '⋈'; const TRUTH: char = '⊤'; const CONSUME: char = '⊥'; const ENGAGE: char = '⊞';
24	
25	fn is_move(mn: &str) -> bool {
26	    matches!(mn, "mov"|"movzx"|"movsx"|"movsxd"|"movabs"|"push"|"pop"|"xchg"|"leave")
27	}
28	fn is_truth(mn: &str) -> bool { matches!(mn, "cmp"|"test") }
29	fn is_terminal(mn: &str) -> bool { mn.starts_with("ret") || matches!(mn, "int3"|"ud2"|"hlt"|"iret"|"retf") }
30	
31	/// The glyph — the same decision vox's classifier makes.
32	pub fn classify(i: &x86::Insn) -> char {
33	    let mn = i.mnemonic.as_str();
34	    if is_terminal(mn) { return TERM; }
35	    if mn == "call" { return if i.target.is_some() { CALL } else { INDIRECT }; }
36	    if mn == "jmp"  { return if i.target.is_some() { XFER } else { INDIRECT }; }
37	    if mn == "syscall" || mn == "sysenter" || mn == "int" { return INDIRECT; }
38	    if mn.starts_with('j') && mn != "jmp" { return SPLIT; }
39	    if mn.starts_with("set") { return CONSUME; }
40	    if mn.starts_with("cmov") { return CONSUME; }
41	    if is_truth(mn) { return TRUTH; }
42	    if i.writes_mem && !is_move(mn) { return COMMIT; }
43	    if is_move(mn) { return LINK; }
44	    ENGAGE
45	}
46	
47	fn fields(ops: &[Op]) -> Vec<String> { ops.iter().map(|o| o.field()).collect() }
48	
49	/// One instruction → its module lines. A merge emits a bare ∋ first.
50	fn encode(i: &x86::Insn, is_merge: bool) -> Vec<String> {
51	    let mut lines: Vec<String> = Vec::new();
52	    if is_merge { lines.push(FUSE.to_string()); }
53	    let mn = i.mnemonic.as_str();
54	    let g = classify(i);
55	    let f = fields(&i.ops);
56	    let join = |parts: &[String]| parts.join("\t");
57	
58	    if g == TERM {
59	        // keep ret's imm16 (stdcall stack cleanup): ⊣  ret  i:0x4
60	        if mn == "ret" && !f.is_empty() { let mut parts=vec![TERM.to_string(), mn.to_string()]; parts.extend(f); lines.push(join(&parts)); }
61	        else { lines.push(format!("{}\t{}", TERM, mn)); }
62	    } else if g == INDIRECT && matches!(mn, "syscall"|"sysenter"|"int") {
63	        lines.push(format!("{}\tsyscall", INDIRECT));
64	    } else if mn == "call" || mn == "jmp" {
65	        let mut parts = vec![g.to_string(), mn.to_string()]; parts.extend(f);
66	        lines.push(join(&parts));
67	    } else if mn.starts_with('j') {
68	        let mut parts = vec![SPLIT.to_string(), mn[1..].to_string()]; parts.extend(f);
69	        lines.push(join(&parts));
70	    } else if mn.starts_with("set") {
71	        let mut parts = vec![CONSUME.to_string(), mn[3..].to_string(), "set".to_string()]; parts.extend(f);
72	        lines.push(join(&parts));
73	    } else if mn.starts_with("cmov") {
74	        let mut parts = vec![CONSUME.to_string(), mn[4..].to_string(), "cmov".to_string()]; parts.extend(f);
75	        lines.push(join(&parts));
76	    } else {
77	        let glyph = if g == TRUTH { TRUTH } else if g == COMMIT { COMMIT } else if g == LINK { LINK } else { ENGAGE };
78	        let mut parts = vec![glyph.to_string(), mn.to_string()]; parts.extend(f);
79	        lines.push(join(&parts));
80	    }
81	    lines
82	}
83	
84	/// Merge points of one function: addresses with ≥2 predecessors.
85	fn merges_of(insns: &[x86::Insn]) -> BTreeSet<u64> {
86	    let aset: BTreeSet<u64> = insns.iter().map(|i| i.addr).collect();
