    pub entry: u64,
    pub code: Vec<(u64, Vec<u8>)>,     // (base address, bytes) of executable segments
    pub data: Vec<(u64, Vec<u8>)>,     // (base address, bytes) the code reads
    pub symbols: BTreeMap<String, u64>,
