}

// ── ELF (32- and 64-bit) ──────────────────────────────────────────────────────
fn elf(raw: &[u8]) -> Loaded {
    let is64 = raw.get(4).copied() == Some(2);
    let mut out = Loaded { entry: 0, code: Vec::new(), data: Vec::new(), symbols: BTreeMap::new(), format: "elf", arch: arch_name(le(raw,18,2), "elf") };
