1	//! Universal executable loader: ELF, PE, Mach-O (including fat), and a raw
2	//! fallback. The x86 decoder and the machine are format-agnostic; they take
3	//! code segments and data segments. This is the one place a file's container is
4	//! read, so every format arrives at the same pipeline: (entry, code, data).
5	//!
6	//! The container is universal; the instruction set is x86-64. A code segment
7	//! that is not x86 simply fails to decode, instruction by instruction, and the
8	//! walk reports how far it got, rather than being refused up front.
9	
10	use alloc::string::String;
11	use alloc::vec::Vec;
12	use alloc::collections::BTreeMap;
13	
14	pub struct Loaded {
15	    pub entry: u64,
16	    pub code: Vec<(u64, Vec<u8>)>,     // (base address, bytes) of executable segments
17	    pub data: Vec<(u64, Vec<u8>)>,     // (base address, bytes) the code reads
18	    pub symbols: BTreeMap<String, u64>,
19	    pub format: &'static str,
20	    /// The machine the code is for, so a non-x86-64 binary is refused rather
21	    /// than silently misdecoded: "x86-64", "x86-32", "arm64", "arm", or a name.
22	    pub arch: &'static str,
23	    /// R_X86_64_IRELATIVE relocations: (GOT slot address, resolver address). A
24	    /// static binary leaves these for its startup to apply — run each resolver,
25	    /// store the pointer it returns in the slot — which is how the CPU-specific
26	    /// memcpy/strlen get chosen. Empty for anything without them.
27	    pub irelative: alloc::vec::Vec<(u64, u64)>,
28	    /// R_X86_64_RELATIVE relocations: (slot, value). A static-pie binary leaves
29	    /// these for its self-relocation to apply — store base+addend at the slot.
30	    /// The VM loads segments at their link addresses, base 0, so the value is
31	    /// the addend. This is how .init_array's function pointers and the GOT come
32	    /// to hold real addresses. Empty for a non-relocated binary.
33	    pub relative: alloc::vec::Vec<(u64, u64)>,
34	}
35	
36	fn arch_name(machine: u64, kind: &str) -> &'static str {
37	    match kind {
38	        "elf" => match machine { 0x3E => "x86-64", 0x03 => "x86-32", 0xB7 => "arm64", 0x28 => "arm", 0xF3 => "riscv", _ => "other" },
39	        "pe"  => match machine { 0x8664 => "x86-64", 0x14c => "x86-32", 0xAA64 => "arm64", 0x1c0|0x1c4 => "arm", _ => "other" },
40	        "macho" => match machine { 0x0100_0007 => "x86-64", 0x0000_0007 => "x86-32", 0x0100_000C => "arm64", 0x0000_000C => "arm", _ => "other" },
41	        _ => "unknown",
42	    }
43	}
44	
45	fn le(raw: &[u8], o: usize, n: usize) -> u64 {
46	    let mut v = 0u64;
47	    for k in 0..n { if o + k < raw.len() { v |= (raw[o + k] as u64) << (8 * k); } }
48	    v
49	}
50	fn be(raw: &[u8], o: usize, n: usize) -> u64 {
51	    let mut v = 0u64;
52	    for k in 0..n { if o + k < raw.len() { v = (v << 8) | raw[o + k] as u64; } }
53	    v
54	}
55	
56	pub fn load(raw: &[u8]) -> Loaded {
57	    if raw.len() >= 4 {
58	        if &raw[0..4] == b"\x7fELF" { return elf(raw); }
59	        if &raw[0..2] == b"MZ"      { return pe(raw); }
60	        let m = le(raw, 0, 4);
61	        if m == 0xFEED_FACF || m == 0xFEED_FACE { return macho(raw, 0); }
62	        if be(raw, 0, 4) == 0xCAFE_BABE         { return macho_fat(raw); }
63	    }
64	    // raw / flat binary: the whole file as code, a conventional load base.
65	    Loaded { entry: 0x1000, code: alloc::vec![(0x1000, raw.to_vec())], data: Vec::new(),
66	             symbols: BTreeMap::new(), irelative: alloc::vec::Vec::new(), relative: alloc::vec::Vec::new(), format: "raw", arch: "x86-64" }
67	}
68	
69	// ── ELF (32- and 64-bit) ──────────────────────────────────────────────────────
70	fn elf(raw: &[u8]) -> Loaded {
71	    let is64 = raw.get(4).copied() == Some(2);
72	    let mut out = Loaded { entry: 0, code: Vec::new(), data: Vec::new(), symbols: BTreeMap::new(), irelative: alloc::vec::Vec::new(), relative: alloc::vec::Vec::new(), format: "elf", arch: arch_name(le(raw,18,2), "elf") };
73	    // header field widths and offsets differ by class
74	    let w = if is64 { 8usize } else { 4 };                 // address width
75	    out.entry = le(raw, 24, w);
76	    let shoff = le(raw, if is64 {0x28} else {0x20}, w) as usize;
77	    let shentsize = le(raw, if is64 {0x3a} else {0x2e}, 2) as usize;
78	    let shnum = le(raw, if is64 {0x3c} else {0x30}, 2) as usize;
79	    // section field offsets: sh_type, sh_flags, sh_addr, sh_offset, sh_size, sh_link, sh_entsize
80	    let (f_flags, f_addr, f_off, f_size, f_link, f_ent) = if is64 {
81	        (8, 16, 24, 32, 40, 56) } else { (8, 12, 16, 20, 24, 36) };
82	    let sh = |k: usize, f: usize, n: usize| le(raw, shoff + k * shentsize + f, n);
83	    for k in 0..shnum {
84	        let sh_type = sh(k, 4, 4);
85	        let sh_flags = sh(k, f_flags, w);
86	        let sh_addr = sh(k, f_addr, w);
87	        let sh_off = sh(k, f_off, w) as usize;
88	        let sh_size = sh(k, f_size, w) as usize;
89	        if sh_type == 1 && sh_off + sh_size <= raw.len() && sh_size > 0 && (sh_flags & 0x2) != 0 {
90	            let bytes = raw[sh_off..sh_off + sh_size].to_vec();
91	            if (sh_flags & 0x4) != 0 { out.code.push((sh_addr, bytes)); }
92	            else { out.data.push((sh_addr, bytes)); }
93	        }
94	    }
95	    // function symbols. Elf32_Sym is 16 bytes (name,value,size,info,other,shndx);
96	    // Elf64_Sym is 24 (name,info,other,shndx,value,size). info and value move.
97	    for k in 0..shnum {
98	        let sh_type = sh(k, 4, 4);
99	        if sh_type != 2 && sh_type != 11 { continue; }
100	        let sym_off = sh(k, f_off, w) as usize; let sym_size = sh(k, f_size, w) as usize;
101	        let strtab = sh(k, f_link, 4) as usize; let str_off = sh(strtab, f_off, w) as usize;
102	        let entsize: usize = if is64 { 24 } else { 16 };
103	        let ent = (sh(k, f_ent, w) as usize).max(entsize);
104	        let mut o = sym_off;
105	        while o + entsize <= sym_off + sym_size && o + entsize <= raw.len() {
106	            let st_name = le(raw, o, 4) as usize;
107	            let (st_info, st_value) = if is64 {
108	                (raw.get(o + 4).copied().unwrap_or(0), le(raw, o + 8, 8))
109	            } else {
110	                (raw.get(o + 12).copied().unwrap_or(0), le(raw, o + 4, 4))
111	            };
112	            if (st_info & 0xf) == 2 && st_value != 0 {
113	                let name = cstr(raw, str_off + st_name);
114	                if !name.is_empty() { out.symbols.insert(name, st_value); }
115	            }
116	            o += ent;
117	        }
118	    }
119	    // IRELATIVE relocations from any SHT_RELA section (.rela.dyn on a static
120	    // binary). Elf64_Rela is r_offset(8) r_info(8) r_addend(8); r_type is the
121	    // low 32 bits of r_info, 0x25 is R_X86_64_IRELATIVE, and its addend is the
122	    // resolver address. 32-bit ELF carries no IRELATIVE, so this is 64-bit only.
123	    if is64 {
124	        for k in 0..shnum {
125	            if sh(k, 4, 4) != 4 { continue; } // SHT_RELA
126	            let r_off = sh(k, f_off, w) as usize;
127	            let r_size = sh(k, f_size, w) as usize;
128	            let mut o = r_off;
129	            while o + 24 <= r_off + r_size && o + 24 <= raw.len() {
130	                let r_offset = le(raw, o, 8);
131	                let r_info = le(raw, o + 8, 8);
132	                let r_addend = le(raw, o + 16, 8);
133	                if (r_info & 0xffff_ffff) == 0x25 { out.irelative.push((r_offset, r_addend)); }
134	                o += 24;
135	            }
136	        }
137	    }
138	    out
139	}
