56	/// The bridge for syscalls the no_std VM cannot fulfill on its own: real files.
57	/// A bare-metal kernel build supplies no `Host`, so `open`/`read`/`write`/
58	/// `close` on any fd — including 0/1/2 — answer -EBADF/-ENOSYS exactly as
59	/// before. A hosted std binary implements this trait once with real
60	/// `std::fs`/stdio and the guest's file and console I/O becomes real: the
61	/// guest reads and writes actual files under whatever permission the host
62	/// process already has, and fd 0/1/2 are real stdin/stdout/stderr.
63	pub trait Host {
64	    fn open(&mut self, path: &str, flags: i32, mode: i32) -> i32;
65	    fn read(&mut self, fd: i32, buf: &mut [u8]) -> i64;
66	    fn write(&mut self, fd: i32, buf: &[u8]) -> i64;
67	    fn close(&mut self, fd: i32) -> i32;
68	}
