70	pub struct Machine {
71	    code: BTreeMap<u64, Vec<(char, Vec<String>)>>,
72	    addrs: Vec<u64>,
73	    next_of: BTreeMap<u64, u64>,
74	    pub entry: u64,
75	    reg: BTreeMap<String, u128>,
76	    mem: BTreeMap<u64, u8>,
77	    flags: (u128, u128, u8),
78	    kind: String,
79	    pub steps: u64,
80	    pub bits: u8,
81	    /// Parsed from the module's own `; sym NAME 0xADDR` lines, so a saved
82	    /// `.imasm` file resolves a symbol name without a second read of the
83	    /// original binary.
84	    pub symbols: BTreeMap<String, u64>,
85	    /// Anonymous-mmap and brk cursors: fresh regions far from any loaded code
86	    /// or data, since `mem` is a sparse map and reads of never-written bytes
87	    /// already come back zero — a freshly "mapped" page needs no zeroing.
88	    mmap_next: u64,
89	    brk_cur: u64,
90	    /// IRELATIVE relocations (slot, resolver) carried by the module. Applied
91	    /// once before a process runs: each resolver is called and its pointer
92	    /// stored in the slot, which is how a static binary's CPU-selected memcpy,
93	    /// strlen and kin get wired before main.
94	    irelative: Vec<(u64, u64)>,
95	    /// RELATIVE relocations (slot, value), stored at load before the process
96	    /// runs — the self-relocation a static-pie binary would do at entry.
97	    relative: Vec<(u64, u64)>,
98	    /// Real file and console I/O, when a hosted caller supplies one.
99	    host: Option<Box<dyn Host>>,
100	    /// Optional trace: addresses to log on entry (allocator functions), and the
