22	fn reg_info(name: &str) -> (&'static str, u8, u8) {
23	    const R64: [&str;16]=["rax","rcx","rdx","rbx","rsp","rbp","rsi","rdi","r8","r9","r10","r11","r12","r13","r14","r15"];
24	    // 64-bit
25	    for &r in R64.iter() { if name == r { return (r, 8, 0); } }
26	    // xmm
27	    if let Some(rest) = name.strip_prefix("xmm") { if rest.parse::<u8>().is_ok() {
28	        // return the canonical static string
29	        const X: [&str;16]=["xmm0","xmm1","xmm2","xmm3","xmm4","xmm5","xmm6","xmm7","xmm8","xmm9","xmm10","xmm11","xmm12","xmm13","xmm14","xmm15"];
30	        return (X[rest.parse::<usize>().unwrap()], 16, 0);
31	    }}
32	    if name == "rip" { return ("rip", 8, 0); }
33	    // The thread-local segment bases, set by arch_prctl and read through every
34	    // TLS access. Full-width pseudo-registers, so the ea() base term "fs" or
35	    // "gs" resolves to the base the guest installed.
36	    if name == "fs" { return ("fs", 8, 0); }
37	    if name == "gs" { return ("gs", 8, 0); }
38	    // e** (32-bit) and r**d
39	    let map32: [(&str,&str);16]=[("eax","rax"),("ecx","rcx"),("edx","rdx"),("ebx","rbx"),("esp","rsp"),("ebp","rbp"),("esi","rsi"),("edi","rdi"),
40	        ("r8d","r8"),("r9d","r9"),("r10d","r10"),("r11d","r11"),("r12d","r12"),("r13d","r13"),("r14d","r14"),("r15d","r15")];
41	    for (n,b) in map32 { if name==n { return (b,4,0); } }
42	    let map16: [(&str,&str);16]=[("ax","rax"),("cx","rcx"),("dx","rdx"),("bx","rbx"),("sp","rsp"),("bp","rbp"),("si","rsi"),("di","rdi"),
43	        ("r8w","r8"),("r9w","r9"),("r10w","r10"),("r11w","r11"),("r12w","r12"),("r13w","r13"),("r14w","r14"),("r15w","r15")];
44	    for (n,b) in map16 { if name==n { return (b,2,0); } }
45	    // 8-bit low
46	    let map8: [(&str,&str);16]=[("al","rax"),("cl","rcx"),("dl","rdx"),("bl","rbx"),("spl","rsp"),("bpl","rbp"),("sil","rsi"),("dil","rdi"),
47	        ("r8b","r8"),("r9b","r9"),("r10b","r10"),("r11b","r11"),("r12b","r12"),("r13b","r13"),("r14b","r14"),("r15b","r15")];
48	    for (n,b) in map8 { if name==n { return (b,1,0); } }
49	    // 8-bit high
50	    for (n,b) in [("ah","rax"),("ch","rcx"),("dh","rdx"),("bh","rbx")] { if name==n { return (b,1,1); } }
51	    ("rax", 8, 0)
52	}
