                            4=>!(x==y), 5=>!(x<y), 6=>!(x<=y), _=>!(x.is_nan()||y.is_nan()) };
        let m = if r { mask(w) } else { 0 };
        o = (o & !(mask(w) << sh)) | (m << sh);
    }
    self.write(&dst, o & mask(16));
    return;
}

