            unsigned long long prod = P * Q;          // both below 2^m<=2^32 here, exact in 64 bits
            if (prod == N) { atomicMin(out, (P < Q) ? P : Q); }
        }
        P = (P * 9ULL) & mask;
        Q = (Q * inv9) & mask;
    }
}
"#;

