1559	pub fn path(rest: &[String]) -> String {
1560	    // Drop only genuine parameter tokens (`rounds=…`). A bare `=` is CLINK, a
1561	    // real opcode: filtering on "contains '='" ate any word carrying it.
1562	    let is_param = |s: &str| {
1563	        ["rounds=", "breadth=", "fixed=", "budget=", "rungs="].iter().any(|p| s.starts_with(p))
1564	            || s == "churn"
1565	    };
1566	    // `churn` after the two words runs the loop's round trip on every waypoint.
1567	    let churn = rest.iter().any(|s| s == "churn");
1568	    // How many axes the inductive ladder climbs before it asks for the name.
1569	    let rungs: usize = rest
1570	        .iter()
1571	        .find_map(|a| a.strip_prefix("rungs=").and_then(|v| v.parse().ok()))
1572	        .unwrap_or(6);
1573	    let words: Vec<&String> = rest.iter().filter(|s| !is_param(s)).collect();
1574	    if words.len() < 2 {
1575	        return "imasm path needs two words: imasm path '<A>' '<B>'\n\
1576	                e.g. ./ask --imasm path '⊢◇>+●¬⊣' '⊢◇>×●¬⊣'\n\
1577	                It finds the promotion path: the shortest walk of single-opcode edits from A \
1578	                to B in which every intermediate is itself a valid program, the program-space \
1579	                analogue of a tuple's promotion path.\n"
1580	            .into();
1581	    }
1582	    // An endpoint may be given as a glyph word OR as a CATALOG ENTRY NAME. An
1583	    // entry already carries its twelve type-glyphs, and each type is itself an
1584	    // IMASM program, so the entry's word is deterministic: no model is asked
1585	    // what an object's word is. Naming the endpoints as objects is what makes
1586	    // the interior tractable — every waypoint sits a known number of edits from
1587	    // two NAMED things, so excribing it is interpolation, not free association.
1588	    let resolve = |raw: &str| -> (String, Option<String>) {
1589	        let looks_glyphic = !raw.chars().any(|c| c.is_alphanumeric());
1590	        if looks_glyphic {
1591	            (raw.to_string(), None)
1592	        } else {
1593	            match crate::imasm::entry_glyph_word(raw) {
1594	                Ok(w) => (w, Some(raw.to_string())),
1595	                Err(_) => (raw.to_string(), None),
1596	            }
1597	        }
1598	    };
1599	    let (word_a, obj_a) = resolve(words[0]);
