\begin{document}
\title{\textbf{The Price-Zero Layer of the Erd\H{o}s--Straus Ladder}}
\author{C.\ Lando Mills\\
Trabuco Canyon, California\\
\texttt{c.landonmills@gmail.com}\\
ORCID: \href{https://orcid.org/0000-0003-0003-0552}{0000-0003-0003-0552}}
\date{11 August 2026}
\maketitle

\begin{abstract}
The Erd\H{o}s--Straus conjecture asserts that $4/n$ is a sum of three unit
fractions for every integer $n \ge 2$. Every congruence class is settled by a
parametric family except $n \equiv 1 \pmod 4$ with $3 \nmid n$, and the
conjecture is equivalent to that class. This paper is about the internal
structure of the class, and the distinction it turns on is between a
representation that is \emph{read off} $n$ and one that must be \emph{searched
for}.

The mechanism is a ladder. For $n \equiv 1 \pmod 4$ and any $r \equiv 3 \pmod 4$
the quantity $a = (n+r)/4$ is an integer and $4/n - 1/a = r/(na)$, so the
numerator of the remainder is not an accident of the greedy step but a chosen
parameter. Splitting that remainder into two unit fractions requires a divisor
$u$ of $M^2$, where $M = na$, satisfying the single congruence $u \equiv -M
\pmod r$; the companion condition on the cofactor is automatic. Everything then
depends on where the divisor comes from. If it is a polynomial in $n$ and $a$,
the representation costs nothing: the rung is read off $n$ and no divisor is
sought. If it requires a prime of $a$ that $n$ does not carry, a search is
unavoidable.

We determine the price-zero layer exactly. Writing the divisor as $u = n^i a^j$
and reducing the congruence modulo $r$, the exponent pairs collapse to four
outcomes, two of which are impossible for $r \equiv 3 \pmod 4$. What survives is
a single criterion: the representation is free whenever some $r \equiv 3 \pmod
4$ divides one of $n$, $n+1$, $n+4$. Each of the three divisibilities carries its
own closed form, and no divisor built from $n$ and $a$ yields anything further.

The layer is large and its complement is sharp. Across $5 \le n \le 200000$ the
criterion together with the case $n \equiv 5 \pmod 8$ represents $32062$ of the
$33333$ values of the class; the $1271$ that remain all satisfy $n \equiv 1
\pmod{24}$, and this containment is a theorem rather than an observation. A
further free family --- a rung dividing $d+1$ for any divisor $d$ of $n$, read
off the factorisation of $n$ alone --- halves that remainder to $638$, and
multiplicative descent leaves $624$, of which $622$ are prime. Cascading the same
divisor test up the ladder closes all but two of those with a rung no larger than
$51$. That thin set, and not the congruence class, is where the conjecture is
still open.
\end{abstract}

\section{The ladder}

Throughout, $n \equiv 1 \pmod 4$ with $3 \nmid n$, and $r$ denotes an integer
with $r \equiv 3 \pmod 4$ and $r \ge 3$, called a \emph{rung}.

\begin{lemma}[Ladder step]
\label{lem:step}
For such $n$ and $r$ the quantity $a = (n+r)/4$ is a positive integer, and
\[
  \frac4n - \frac1a \;=\; \frac{4a - n}{na} \;=\; \frac{r}{na}.
\]
\end{lemma}

\begin{proof}
$n + r \equiv 1 + 3 \equiv 0 \pmod 4$, so $a$ is an integer, and it is positive
because $n, r > 0$. The displayed identity is the definition of $a$ substituted
into $4/n - 1/a$.
\end{proof}

Write $M = na$. What remains is to split $r/M$ into two unit fractions.

\begin{lemma}[The splitting criterion]
\label{lem:crit}
Let $u, v$ be positive integers with $uv = M^2$ and $r \mid M + u$. If
$b = (M+u)/r$ and $c = (M+v)/r$ are integers then
\[
  \frac{r}{M} \;=\; \frac1b + \frac1c .
\]
Moreover, if $\gcd(r,M) = 1$ then $r \mid M+v$ follows from $r \mid M+u$, so the
criterion is a single congruence on a single divisor.
\end{lemma}

\begin{proof}
From $uv = M^2$,
\[
  (M+u)(M+v) \;=\; M^2 + Mv + Mu + uv \;=\; M\,(2M + u + v),
\]
so $\frac1b + \frac1c = \frac{r(b+c)}{r^2 bc} = \frac{r\,(2M+u+v)}{(M+u)(M+v)}
= \frac{r}{M}$. For the second statement, work modulo $r$: the hypothesis reads
$u \equiv -M$, so $M^2 = uv \equiv -Mv$, hence $M(M+v) \equiv 0$, and $M$ is
invertible.
\end{proof}

\begin{definition}
The pair $(r,u)$ \emph{closes} $n$ when $a = (n+r)/4$, $M = na$, $u \mid M^2$ and
$r \mid M + u$. By \Cref{lem:step} and \Cref{lem:crit} a closing pair yields
\[
  \frac4n \;=\; \frac1a + \frac1b + \frac1c ,
  \qquad b = \frac{M+u}{r}, \quad c = \frac{M + M^2/u}{r}.
\]
\end{definition}

The conjecture, restricted to the surviving class, is the assertion that every
$n$ admits a closing pair. The question this paper answers is which $n$ admit one
whose divisor is a polynomial in $n$ and $a$, so that nothing is searched.

\begin{proposition}[Unified algebraic ladder identity]
\label{prop:general-ladder}
Let $r, t \ge 1$ with $r \mid t + 1$, and set $K = (t+1)/r$. Whenever $4a = n + r$
and $t \mid a$, the three unit fractions
\[
  \frac4n \;=\; \frac1a + \frac{1}{Kna} + \frac{1}{Kn(a/t)}
\]
sum identically to $4/n$.
\end{proposition}

\begin{proof}
Directly,
\[
  \frac{1}{Kna} + \frac{1}{Kn(a/t)}
  \;=\; \frac{1}{Kna}\Big(1 + t\Big)
  \;=\; \frac{t+1}{Kna}
  \;=\; \frac{rK}{Kna}
  \;=\; \frac{r}{na}.
\]
Adding $1/a$ gives $(na + ra)/(na^2) = (n+r)/(na) = 4a/(na) = 4/n$.
\end{proof}

When $t \mid a$, the condition $r \mid t + 1$ matches the splitting criterion with
divisor $u = na/t$, and whenever $n$ satisfies a congruence ensuring $t \mid a$,
this identity produces an explicit covering progression without search.

\section{Three free families}

\begin{theorem}[$r \mid n+1$]
\label{thm:np1}
If $r \mid n+1$ then, with $4a = n+r$ and $rb = a(n+1)$,
\[
  \frac4n \;=\; \frac1a + \frac1b + \frac1{nb}.
\]
\end{theorem}

\begin{proof}
$b$ is an integer because $r$ divides $n+1$. Then
\[
  \frac1b + \frac1{nb} \;=\; \frac{n+1}{nb} \;=\; \frac{r(n+1)}{n\,r b}
  \;=\; \frac{r(n+1)}{n\,a(n+1)} \;=\; \frac{r}{na},
\]
and \Cref{lem:step} adds $1/a$ to give $4/n$. The divisor here is $u = a$.
\end{proof}

\begin{theorem}[$r \mid n+4$]
\label{thm:np4}
If $r \mid n+4$ then $r \mid a+1$, and with $rb = n(a+1)$ and $c = ab$,
\[
  \frac4n \;=\; \frac1a + \frac1b + \frac1c .
\]
\end{theorem}

\begin{proof}
From $4a = n+r$ we get $4(a+1) = (n+4) + r$, so $r \mid 4(a+1)$; as $r$ is odd it
is coprime to $4$ and $r \mid a+1$. Hence $b$ is an integer, and
\[
  \frac1b + \frac1{ab} \;=\; \frac{a+1}{ab} \;=\; \frac{r(a+1)}{a\,rb}
  \;=\; \frac{r(a+1)}{a\,n(a+1)} \;=\; \frac{r}{na}.
\]
The divisor is $u = n$, whose cofactor is $v = na^2$, which is why the third
denominator is $a$ times the second.
\end{proof}

\begin{theorem}[$r \mid n$]
\label{thm:n}
If $r \mid n$ then, with $rb = 2na$,
\[
  \frac4n \;=\; \frac1a + \frac1b + \frac1b .
\]
\end{theorem}

\begin{proof}
$b$ is an integer since $r \mid n$. Then $1/b + 1/b = 2/b = r/(na)$, and
\Cref{lem:step} finishes. The divisor is $u = M$ itself, admissible precisely
because $M \equiv 0 \pmod r$.
\end{proof}

Each of the three is a closed form: given $n$, one exhibits $r$ as a divisor of a
number $n$ already carries, and the three denominators are then written down.

A fourth family costs nothing either, and it is not of monomial type, so
\Cref{thm:exhaust} does not speak to it: it takes its divisor from the
factorisation of $n$.

\begin{theorem}[The shift family]
\label{thm:shift}
Let $d \mid n$ with $d > 1$, and let $r \equiv 3 \pmod 4$ divide $d+1$. Then with
$4a = n+r$ and $M = na = ud$,
\[
  \frac4n \;=\; \frac1a + \frac1b + \frac1c, \qquad
  b = \frac{M+u}{r}, \quad c = \frac{M+M^2/u}{r}.
\]
\end{theorem}

\begin{proof}
$d \mid n \mid M$, so $M = ud$ for an integer $u$, and $M + u = u(d+1)$ is
divisible by $r$. \Cref{lem:crit} supplies $b$ and $c$.
\end{proof}

The family is genuinely wider than $r \mid n+1$, which is the case $d = n$: it
asks the shift of \emph{any} divisor, and for composite $n$ that is many
chances rather than one. It closes $633$ of the $1271$ values \Cref{thm:mod24} leaves, halving that
remainder before descent is applied at all.

\section{The layer is exactly these three}

\begin{lemma}
\label{lem:nsq4}
No divisor of $n^2 + 4$ is congruent to $3$ modulo $4$.
\end{lemma}

\begin{proof}
$n$ is odd, so $n^2 + 4$ is odd, and $\gcd(n,2) = 1$, so every prime $p$
dividing $n^2 + 2^2$ satisfies $p \equiv 1 \pmod 4$. A product of such primes is
$1$ modulo $4$, and so is every divisor.
\end{proof}

\begin{theorem}[Exhaustion]
\label{thm:exhaust}
Let $r \equiv 3 \pmod 4$, $r \ge 3$, $r \nmid n$, and let the divisor be a
monomial $u = n^i a^j$. Admissibility $u \mid M^2 = n^2 a^2$ forces
$i, j \le 2$, and under that constraint the congruence $r \mid M + u$ holds only
if
\[
  \boxed{\;r \mid n+1 \quad\text{or}\quad r \mid n+4.\;}
\]
\end{theorem}

\begin{proof}
Modulo $r$ we have $4a \equiv n$, so $a \equiv n\bar4$ with $\bar4$ the inverse
of $4$, which exists because $r$ is odd. Then $M \equiv n^2\bar4$ and $u \equiv
n^{i+j}\bar4^{\,j}$, and multiplying $M + u \equiv 0$ by $4^{\,j+1}$ gives
\[
  4^{\,j} n^2 + 4\,n^{\,i+j} \;\equiv\; 0 \pmod r .
\]
Since $r \nmid n$, the factor $n^{\min(2,\,i+j)}$ cancels. The nine admissible
pairs $(i,j)$ then reduce as follows.
\begin{itemize}
\item $(2,2)$ and $(0,0)$ give $r \mid n^2 + 4$, excluded by \Cref{lem:nsq4}.
\item $(1,1)$ gives $r \mid 8$, and $(2,0)$, $(0,2)$ give $r \mid 5$ and
  $r \mid 20$; none of $8$, $5$, $20$ has a divisor $\equiv 3 \pmod 4$.
\item $(0,1)$ and $(2,1)$ give $4n + 4 \equiv 0$, hence $r \mid n+1$.
\item $(1,0)$ and $(1,2)$ give $n + 4 \equiv 0$, hence $r \mid n+4$.
\end{itemize}
Every case is one of the two stated conclusions or impossible.
\end{proof}

\begin{corollary}[The price-zero criterion]
\label{cor:pz}
If some $r \equiv 3 \pmod 4$, $r \ge 3$, divides one of $n$, $n+1$, $n+4$, then
$4/n$ is a sum of three unit fractions written in closed form; and no divisor
of the monomial shape yields a representation for any other $n$.
\end{corollary}

\begin{proof}
The first half is \Cref{thm:np1}, \Cref{thm:np4} and \Cref{thm:n}; the second is
\Cref{thm:exhaust}.
\end{proof}

\section{The frontier}

Two further mechanisms cost nothing. The first is the case $n \equiv 5 \pmod 8$:
there $a = (n+3)/4$ is even, so $u = 2$ divides $M$, and the congruence $3 \mid
M+2$ amounts to $3 \mid n^2 + 8$, which holds identically for $3 \nmid n$. The
second is multiplicative descent: if $d \mid n$ with $d > 1$ and $4/d = 1/x +
1/y + 1/z$, then scaling each denominator by $n/d$ represents $4/n$.

\begin{definition}
Call $n$ a \emph{frontier value} when $n \equiv 1 \pmod 4$, $3 \nmid n$,
$n \not\equiv 5 \pmod 8$, and no $r \equiv 3 \pmod 4$ with $r \ge 3$ divides any
of $n$, $n+1$, $n+4$.
\end{definition}

\begin{theorem}[The frontier lies on one class]
\label{thm:mod24}
Every frontier value satisfies $n \equiv 1 \pmod{24}$.
\end{theorem}

\begin{proof}
Since $n \equiv 1 \pmod 4$, $n$ is odd and $n \bmod 8 \in \{1,5\}$; the second is
excluded by hypothesis, so $n \equiv 1 \pmod 8$. For the other factor, $3 \nmid
n$ leaves $n \equiv 1$ or $2 \pmod 3$; if $n \equiv 2$ then $3 \mid n+1$ and $3$
is itself a rung, contradicting the hypothesis. Hence $n \equiv 1 \pmod 3$, and
the two congruences combine to $n \equiv 1 \pmod{24}$.
\end{proof}

Equivalently, a frontier value is one for which $n$, $n+4$ and $(n+1)/2$ are all
products of primes congruent to $1$ modulo $4$. The condition is restrictive, and
the count reflects it. Of the $33333$ values of the surviving class below
$200000$, the price-zero criterion and the case $n \equiv 5 \pmod 8$ together
represent $32062$, or $96.2\%$. Adjoining \Cref{thm:shift} and multiplicative
descent brings the total to $32709$ and leaves $624$ values, of which $622$ are
prime, beginning
\[
  193,\; 313,\; 457,\; 673,\; 1009,\; 1153,\; 1201,\; 1321,\; 1489,\; 1873.
\]
That the survivors are almost all prime is the expected shape: descent means a
composite survives only when every factor does.

For a frontier value the divisor $u$ must therefore involve a prime of $a$ that
$n$ does not carry, and since $a$ depends on the rung, the rung must be walked.
That is a search over $r$, and it is the only search the ladder ever needs.
Empirically the walk is short and its growth fits a fourth root. Over
$5 \le n \le 4 \cdot 10^6$ the least closing rung never exceeds $71$; the values
forcing a higher rung than anything before them are
\[
  n = 5,\,49,\,1129,\,1201,\,21169,\,118801,\,1430641,
  \qquad r = 3,\,7,\,11,\,23,\,31,\,59,\,71,
\]
and $r / \lfloor n^{1/4} \rfloor$ at those records is $3.0$, $3.5$, $2.2$, $4.6$,
$2.6$, $3.3$, $2.1$, while the block from $2 \cdot 10^6$ to $4 \cdot 10^6$ tops
out at rung $55$ with ratio $1.4$. The ratio is largest at small $n$, so
$Cn^{1/4}$ fits with $C$ a little above $4.6$, the binding constant coming from
$n = 1201$ rather than from the large values.
Whether any bound holds in general is the open question, now stated about a set
of density under two percent rather than about a congruence class.

\section{The ladder loses nothing}

Everything so far produces representations. What remains is to know that the
ladder cannot miss one --- that no representation of $4/n$ lies outside it.

\begin{theorem}[Completeness]
\label{thm:complete}
Let $4/n = 1/x + 1/y + 1/z$ with $x \le y \le z$ positive integers. Put
$r = 4x - n$ and $M = nx$. Then $r$ is a positive integer with $r \equiv 3 \pmod
4$, and $u = ry - M$, $v = rz - M$ are positive with
\[
  uv = M^2, \qquad r \mid M + u, \qquad r \mid M + v .
\]
Conversely, any such $r$, $u$, $v$ give a representation with denominators
$x = (n+r)/4$, $y = (M+u)/r$, $z = (M+v)/r$.
\end{theorem}

\begin{proof}
$x$ is the smallest denominator, so $1/x \ge \frac13 \cdot 4/n$ and in particular
$4x > n$, making $r$ positive; $n \equiv 1 \pmod 4$ gives $r \equiv 3$. Clearing
denominators in $1/y + 1/z = 4/n - 1/x = r/M$ gives $M(y+z) = ryz$. Hence
\[
  (M+u)(M+v) \;=\; (ry)(rz) \;=\; r \cdot \big(M(y+z)\big) \;=\; M\big((M+u) + (M+v)\big),
\]
and expanding both sides leaves $uv = M^2$. Positivity of $u$ follows from
$1/y < r/M$. The divisibility statements are $M + u = ry$ and $M + v = rz$. The
converse is \Cref{lem:step} and \Cref{lem:crit}.
\end{proof}

So the rung and the divisor are not a method for finding representations; they
are a coordinate system on the set of them. The conjecture restricted to the
surviving class says exactly that every $n$ has a rung whose $M^2$ carries a
divisor at $-M$, and a value with no such rung would have no representation at
all.

\section{The searched rung is a group condition}

For a frontier value the divisor cannot be a monomial in $n$ and $a$, so it must
draw on the primes of $M = na$ themselves, and the criterion becomes a question
about a multiplicative group. Write $M = \prod_i p_i^{e_i}$. The divisors of
$M^2$ reduce modulo $r$ to the reachable set
\[
  R \;=\; \Big\{ \textstyle\prod_i p_i^{f_i} \bmod r \;:\; 0 \le f_i \le 2e_i \Big\},
\]
and by \Cref{lem:crit} the rung closes exactly when $-M \in R$.

\begin{proposition}
\label{prop:minusone}
$M \in R$, so $-M \in R$ implies $-1 \in H$, where $H \le (\mathbb{Z}/r)^\times$
is the subgroup generated by the residues of $p_1, \dots, p_k$. Conversely, if
some divisor $t$ of $M$ satisfies $t \equiv -1 \pmod r$, then $u = M t$ divides
$M^2$ and $M + u = M(1+t) \equiv 0 \pmod r$, so the rung closes.
\end{proposition}

\begin{proof}
Taking $f_i = e_i$ gives $M \in R$, and $R \subseteq H$ because every element of
$R$ is a product of the generators. For the converse, $t \mid M$ gives
$Mt \mid M^2$, and the congruence is immediate.
\end{proof}

The two halves do not meet, and the distance between them is the exponent budget
rather than the group. Membership $-1 \in H$ allows arbitrary exponents;
membership $-1 \in R$ caps them at $2e_i$. The gap is real and it thins. Across the frontier it appears at $19$ of the $379$
rungs walked below $50000$, at $21$ of $850$ from there to $200000$, and at $15$
of $974$ to $400000$ --- $5.0\%$, $2.5\%$, $1.5\%$. More primes in $M$ means a
larger reachable set, so the group criterion and the real one converge as $n$
grows. What is exceptional is a value that fails this way at \emph{every}
rung: $n = 2521$ does. Searched to rung $4000$, no $M = 2521(2521+r)/4$ carries a
divisor at $-1$, so its divisor genuinely lives in $M^2$ rather than beyond a
small budget --- while $n = 196561$ acquires a cofactor at rung $75$ and
$n = 1201$ at rung $23$. Elsewhere the gap costs a rung and the walk continues; every other failing
rung fails for the other reason, that the subgroup itself lacks $-1$. At $n = 1201$ and $r = 11$ we have $M = 3 \cdot 101 \cdot 1201$ with
residues $3, 2, 2$; the subgroup they generate is all of $(\mathbb{Z}/11)^\times$,
so $-1 \in H$, but $-1 \equiv 2^5$ and the squarefree $M$ offers a total exponent
of $4$ on the residue $2$. The rung does not close, and $n = 1201$ waits until
$r = 23$. Every instance of the gap has this shape: $M$ squarefree, $H$ the full
group, and $-1$ sitting at a power the available exponents cannot write.

This is why the least closing rung tracks the factorisation of $na$ rather than
the size of $n$. The subgroup $H$ is generated by the residues of the primes of
$M$, and $M$ changes with the rung, since $a = (n+r)/4$ does; so the walk over
$r$ is a walk over group conditions, each with its own exponent budget, and its
length is governed by how quickly a rung arrives whose primes both generate $-1$
and supply the exponents to write it.

\section{Reading the rung off $kn+1$}

The cofactor of \Cref{prop:minusone} satisfies $w \equiv -1 \pmod r$, so
$w = kr - 1$ for some $k \ge 1$ and the rung is $r = (w+1)/k$. The requirement
$w \mid M$ then becomes a condition on $n$ alone, with no reference to $a$.

\begin{theorem}[The $k$-shift family]
\label{thm:kshift}
Let $k \ge 1$ and let $w \mid kn+1$ with $\gcd(w, 4k) = 1$, $k \mid w+1$ and
$r = (w+1)/k \equiv 3 \pmod 4$. Then $r$ closes $n$.
\end{theorem}

\begin{proof}
From $4a = n+r$, multiplying by $k$ gives $4ka = kn + kr = (kn+1) + w$, and $w$
divides both summands on the right, so $w \mid 4ka$; being coprime to $4k$ it
divides $a$, hence $M$. Its cofactor $u = M/w$ satisfies $M + u = u(w+1)$, which
$r$ divides because $w + 1 = kr$.
\end{proof}

\begin{corollary}[$k=2$]
\label{cor:twoshift}
If $2n+1$ has a divisor $w \equiv 5 \pmod 8$, then $4/n$ is a sum of three unit
fractions, at the rung $(w+1)/2$.
\end{corollary}

\begin{proof}
$w$ is odd, hence coprime to $8$, and $w \equiv 5 \pmod 8$ makes
$(w+1)/2 \equiv 3 \pmod 4$. Apply \Cref{thm:kshift} with $k = 2$.
\end{proof}

This is the resolution of the apparent circularity. The divisor search wanted a
factor of $M = na$, and $a$ depended on the rung being tested; the family above
replaces that by a search over $k$, where each $k$ requires only the
factorisation of $kn+1$. The case $k=1$ is \Cref{thm:np1}. The reparametrization is exact rather than partial: every cofactor is $kr-1$ for
some $k$, so no representation is lost. But $k$ is not bounded a priori --- it
reaches $(M+1)/r$ --- which makes $k$ the wrong axis to search along. Read from
the rung side, each cofactor handing back its own $k = (w+1)/r$, the $624$
frontier values below $200000$ have least $k \le 2$ in $314$ cases, $k \le 8$ in
$565$, $k \le 32$ in $613$, and a tail reaching $k = 12813$ at $n = 66529$, rung
$135$. Only even $k$ occur, since $w$ must be odd wherever $M$ is.

With rungs allowed up to $200$, exactly one frontier value below $200000$ has no
cofactor of $M$ at any rung and genuinely requires a divisor of $M^2$, namely
$n = 2521$; the case $n = 196561$ needs only a rung beyond $51$.

The frontier thins as the range moves out, and the cofactor form keeps up with
it. Taking the surviving class in blocks of $33333$ values:
\begin{center}
\begin{tabular}{lrrrr}
\toprule
range & frontier & prime & least $k \le 8$ & needing $M^2$ \\
\midrule
$5$--$200000$        & 624 & 622 & 565 & 1 \\
$200001$--$400000$   & 486 & 484 & 449 & 0 \\
$400001$--$600000$   & 444 & 440 & 401 & 0 \\
$600001$--$800000$   & 395 & 393 & 363 & 0 \\
$800001$--$1000000$  & 390 & 388 & 352 & 0 \\
\bottomrule
\end{tabular}
\end{center}
The frontier's share of the class falls from $1.9\%$ through $1.5\%$, $1.3\%$ and
$1.2\%$ to $1.2\%$, its members remain almost entirely prime --- two composites
per block, each a product of frontier primes, as \Cref{thm:complete}'s companion
descent requires --- and the largest least-$k$ observed is $15083$, at
$n = 297889$ on rung $79$. Across all five blocks, covering the surviving class
to $10^6$, a cofactor of $M$ exists at a rung no larger than $200$ for every
value but $n = 2521$.

Each $k$ therefore imposes its own multiplicative condition on a value that
survives: no divisor of $kn+1$ in the residue class that would produce a rung.
For $k = 2$ that condition is that $2n+1$ has no divisor $\equiv 5 \pmod 8$, and
$n = 193$ shows it can hold --- $2n+1 = 387 = 3^2 \cdot 43$, whose divisors are
$1, 3, 9, 43, 129, 387$, none of them $\equiv 5 \pmod 8$. What cuts the frontier
down is thus a growing family of independent conditions rather than one
obstruction, which is the same shape as \Cref{cor:squeeze} at a larger scale.

\section{The cascade}

\Cref{prop:minusone} asks for a divisor of $M$ at $-1$; equivalently, for a
factorisation $M = uw$ whose \emph{cofactor} $w$ satisfies $w \equiv -1 \pmod r$,
since then $M + u = u(w+1)$. This is the form the frontier's witnesses actually
take, and at the greedy rung it reduces to a statement about primes.

\begin{theorem}[The greedy rung]
\label{thm:rung3}
Let $n$ be a frontier value, $a = (n+3)/4$ and $M = na$. Then $M \equiv 1 \pmod
3$, and if any prime factor $p$ of $M$ satisfies $p \equiv 2 \pmod 3$, the rung
$r = 3$ closes: with $u = M/p$,
\[
  \frac4n \;=\; \frac1a + \frac1b + \frac1c, \qquad
  b = \frac{M+u}{3}, \quad c = \frac{M + M^2/u}{3}.
\]
\end{theorem}

\begin{proof}
A frontier value has $n \equiv 1 \pmod 3$, and $4a = n+3$ forces $a \equiv 1$, so
$M \equiv 1$. Taking $w = p$ gives $M = uw$ with $3 \mid w+1$, hence $3 \mid M+u$,
and \Cref{lem:crit} supplies $b$ and $c$. Conversely a divisor of $M$ at $2$
exists only if some prime factor sits there, because a product of primes
$\equiv 1$ is $\equiv 1$.
\end{proof}

\begin{corollary}[The cost of surviving the greedy rung]
\label{cor:squeeze}
If rung $3$ does not close a frontier value by the cofactor form, then every
prime factor of $M = n(n+3)/4$ is $\equiv 1 \pmod 3$. Combined with the frontier
condition itself, such an $n$ satisfies four multiplicative constraints at once:
$n$ and $n+4$ are products of primes $\equiv 1 \pmod 4$, and $n$ and $(n+3)/4$
are products of primes $\equiv 1 \pmod 3$.
\end{corollary}

\begin{proof}
Contrapositive of \Cref{thm:rung3}, together with the definition of a frontier
value.
\end{proof}

Cascading the cofactor test up the ladder gives the following, over the $624$
frontier values below $200000$.

\begin{center}
\begin{tabular}{rrr}
\toprule
rung & closed here & still open \\
\midrule
 3 & 313 & 311 \\
 7 & 202 & 109 \\
11 &  55 &  54 \\
15 &  15 &  39 \\
19 &   8 &  31 \\
23 &  19 &  12 \\
27 &   2 &  10 \\
31 &   5 &   5 \\
39 &   3 &   2 \\
\bottomrule
\end{tabular}
\end{center}

Two values are not reached by any cofactor of $M$ with $r \le 51$. At $n = 2521$
the divisor genuinely lies in $M^2$ and the rung is $23$; at $n = 196561$ a
cofactor exists at a rung beyond $51$, and the $M^2$ route reaches it at $27$, where $M = 7^2 \cdot 17 \cdot 59 \cdot 196561$ and the
closing divisor is $u = 7^4 \cdot 17$, the fourth power of $7$ being available
only after squaring. That is precisely the exponent budget of
\Cref{prop:minusone} being exercised, and it is exercised twice below $200000$.

So the frontier is not a wall but a cascade with a known shape: half of it falls
to a single prime residue at the greedy rung, the remainder falls to the same
test at higher rungs, and what survives that is the pair of values where the
squared exponents matter.

\section{Position}

Settled: the completeness of the ladder, the unified algebraic ladder identity,
the three closed forms and their exhaustion among monomial divisors, the shift
and $k$-shift families, the cofactor criterion and its prime form at the greedy
rung, the containment of the frontier in $n \equiv 1 \pmod{24}$, and the reduction
of the conjecture on the surviving class to the frontier values. The general
ladder identity, the three closed forms, the criterion assembled from them,
multiplicative descent, and the containment are formalised in \Lean{} against
Mathlib, each depending only on \texttt{propext}, \texttt{Classical.choice} and
\texttt{Quot.sound}; the exhaustion theorem is proved here by the modular
enumeration above.

Open: a bound on the least closing rung, which by the section above is the
statement that settles the rest. The group reading of \Cref{prop:minusone} makes
it concrete: a bound follows from knowing how soon, along $r \equiv 3 \pmod 4$,
the primes of $n(n+r)/4$ both generate $-1$ modulo $r$ and carry the exponents to
express it.

\section{What a bound would have to say}

Three statements sit between the ladder and the conjecture on this class, ordered
by strength.

The weakest is that every $n$ has some rung. By \Cref{thm:complete} that is the
conjecture on the class, neither more nor less.

The middle one asks for a rung at which $M$ itself, rather than $M^2$, carries a
divisor at $-1$. It is strictly stronger: $n = 2521$ has no such rung below $4000$
and yet closes, so the gap between the two statements is inhabited rather than
notional.

The strongest is a bound: a function $B$ with a closing rung below $B(n)$ for
every $n$ in the class. All blocks measured are consistent with
$B(n) = Cn^{1/4}$, $C$ a little above $4.6$. A bound of any shape settles the conjecture on every range it
covers, because the rungs below it are finitely many and each is decidable by the
criterion of \Cref{lem:crit}; and by \Cref{cor:squeeze} and the $k$-shift reading,
a value forcing a large rung must satisfy a growing list of independent
multiplicative conditions. That is the statement worth attacking, and it is
arithmetic about the primes of $n(n+r)/4$ rather than anything about unit
fractions.

