# Verify the paper's own two hardest cases by direct computation, and push the
# search well past where the paper stopped (r=51 for M, r<=200 for k-shift) to
# see how far reaching the rung actually needs to go for n=2521 and n=196561.

def factorize(n):
    f = {}
    d = 2
    while d*d <= n:
        while n % d == 0:
            f[d] = f.get(d,0)+1; n //= d
        d += 1
    if n > 1: f[n] = f.get(n,0)+1
    return f

def divisors_of(n):
    f = factorize(n)
    divs = [1]
    for p, e in f.items():
        divs = [d * p**k for d in divs for k in range(e+1)]
    return divs

def m_route_rung(n, max_r):
    """Search for r with a plain divisor of M (not M^2) closing n."""
    for r in range(3, max_r, 4):
        if (n+r) % 4 != 0: continue
        a = (n+r)//4
        M = n*a
        target = (-M) % r
        for u in divisors_of(M):
            if u % r == target:
                return r, u, M
    return None

def m2_route_rung(n, max_r):
    """Search for r with a divisor of M^2 (via cofactor t | M, u = M*t) closing n."""
    for r in range(3, max_r, 4):
        if (n+r) % 4 != 0: continue
        a = (n+r)//4
        M = n*a
        target = (-M) % r
        for t in divisors_of(M):
            u = M * t
            if u % r == target:
                return r, u, M, t
    return None

for n in (2521, 196561):
    print(f"=== n = {n} ===")
    m = m_route_rung(n, 4000)
    print(f"  plain M-divisor route, searched r<4000: {m if m else 'no closing rung found'}")
    m2 = m2_route_rung(n, 200)
    print(f"  M^2-route (cofactor of M), searched r<200: {m2}")
