46	\begin{document}
47	\title{\textbf{The Price-Zero Layer of the Erd\H{o}s--Straus Ladder}}
48	\author{C.\ Lando Mills\\
49	Trabuco Canyon, California\\
50	\texttt{c.landonmills@gmail.com}\\
51	ORCID: \href{https://orcid.org/0000-0003-0003-0552}{0000-0003-0003-0552}}
52	\date{11 August 2026}
53	\maketitle
54	
55	\begin{abstract}
56	The Erd\H{o}s--Straus conjecture asserts that $4/n$ is a sum of three unit
57	fractions for every integer $n \ge 2$. Every congruence class is settled by a
58	parametric family except $n \equiv 1 \pmod 4$ with $3 \nmid n$, and the
59	conjecture is equivalent to that class. This paper is about the internal
60	structure of the class, and the distinction it turns on is between a
61	representation that is \emph{read off} $n$ and one that must be \emph{searched
62	for}.
63	
64	The mechanism is a ladder. For $n \equiv 1 \pmod 4$ and any $r \equiv 3 \pmod 4$
65	the quantity $a = (n+r)/4$ is an integer and $4/n - 1/a = r/(na)$, so the
66	numerator of the remainder is not an accident of the greedy step but a chosen
67	parameter. Splitting that remainder into two unit fractions requires a divisor
68	$u$ of $M^2$, where $M = na$, satisfying the single congruence $u \equiv -M
69	\pmod r$; the companion condition on the cofactor is automatic. Everything then
70	depends on where the divisor comes from. If it is a polynomial in $n$ and $a$,
71	the representation costs nothing: the rung is read off $n$ and no divisor is
72	sought. If it requires a prime of $a$ that $n$ does not carry, a search is
73	unavoidable.
74	
75	We determine the price-zero layer exactly. Writing the divisor as $u = n^i a^j$
76	and reducing the congruence modulo $r$, the exponent pairs collapse to four
77	outcomes, two of which are impossible for $r \equiv 3 \pmod 4$. What survives is
78	a single criterion: the representation is free whenever some $r \equiv 3 \pmod
79	4$ divides one of $n$, $n+1$, $n+4$. Each of the three divisibilities carries its
80	own closed form, and no divisor built from $n$ and $a$ yields anything further.
81	
82	The layer is large and its complement is sharp. Across $5 \le n \le 200000$ the
83	criterion together with the case $n \equiv 5 \pmod 8$ represents $32062$ of the
84	$33333$ values of the class; the $1271$ that remain all satisfy $n \equiv 1
85	\pmod{24}$, and this containment is a theorem rather than an observation. A
86	further free family --- a rung dividing $d+1$ for any divisor $d$ of $n$, read
87	off the factorisation of $n$ alone --- halves that remainder to $638$, and
88	multiplicative descent leaves $624$, of which $622$ are prime. Cascading the same
89	divisor test up the ladder closes all but two of those with a rung no larger than
90	$51$ by a divisor of $M$, and both of the two remaining close as well, by a
91	divisor of $M^2$ at rungs $23$ and $27$. Nothing in the surviving class below
92	$200000$ is left open by this construction; what remains open is a bound on the
93	rung, general in $n$ rather than checked case by case.
94	\end{abstract}
95	
96	\section{The ladder}
97	
98	Throughout, $n \equiv 1 \pmod 4$ with $3 \nmid n$, and $r$ denotes an integer
99	with $r \equiv 3 \pmod 4$ and $r \ge 3$, called a \emph{rung}.
100	
101	\begin{lemma}[Ladder step]
102	\label{lem:step}
103	For such $n$ and $r$ the quantity $a = (n+r)/4$ is a positive integer, and
104	\[
105	  \frac4n - \frac1a \;=\; \frac{4a - n}{na} \;=\; \frac{r}{na}.
106	\]
107	\end{lemma}
108	
109	\begin{proof}
110	$n + r \equiv 1 + 3 \equiv 0 \pmod 4$, so $a$ is an integer, and it is positive
111	because $n, r > 0$. The displayed identity is the definition of $a$ substituted
112	into $4/n - 1/a$.
113	\end{proof}
114	
115	Write $M = na$. What remains is to split $r/M$ into two unit fractions.
116	
117	\begin{lemma}[The splitting criterion]
118	\label{lem:crit}
119	Let $u, v$ be positive integers with $uv = M^2$ and $r \mid M + u$. If
120	$b = (M+u)/r$ and $c = (M+v)/r$ are integers then
121	\[
122	  \frac{r}{M} \;=\; \frac1b + \frac1c .
123	\]
124	Moreover, if $\gcd(r,M) = 1$ then $r \mid M+v$ follows from $r \mid M+u$, so the
125	criterion is a single congruence on a single divisor.
126	\end{lemma}
127	
128	\begin{proof}
129	From $uv = M^2$,
130	\[
131	  (M+u)(M+v) \;=\; M^2 + Mv + Mu + uv \;=\; M\,(2M + u + v),
132	\]
133	so $\frac1b + \frac1c = \frac{r(b+c)}{r^2 bc} = \frac{r\,(2M+u+v)}{(M+u)(M+v)}
134	= \frac{r}{M}$. For the second statement, work modulo $r$: the hypothesis reads
135	$u \equiv -M$, so $M^2 = uv \equiv -Mv$, hence $M(M+v) \equiv 0$, and $M$ is
136	invertible.
137	\end{proof}
138	
139	\begin{definition}
140	The pair $(r,u)$ \emph{closes} $n$ when $a = (n+r)/4$, $M = na$, $u \mid M^2$ and
141	$r \mid M + u$. By \Cref{lem:step} and \Cref{lem:crit} a closing pair yields
142	\[
143	  \frac4n \;=\; \frac1a + \frac1b + \frac1c ,
144	  \qquad b = \frac{M+u}{r}, \quad c = \frac{M + M^2/u}{r}.
145	\]
146	\end{definition}
147	
148	The conjecture, restricted to the surviving class, is the assertion that every
149	$n$ admits a closing pair. The question this paper answers is which $n$ admit one
150	whose divisor is a polynomial in $n$ and $a$, so that nothing is searched.
151	
152	\section{Three free families}
153	
154	\begin{theorem}[$r \mid n+1$]
155	\label{thm:np1}
156	If $r \mid n+1$ then, with $4a = n+r$ and $rb = a(n+1)$,
157	\[
158	  \frac4n \;=\; \frac1a + \frac1b + \frac1{nb}.
159	\]
160	\end{theorem}
161	
162	\begin{proof}
163	$b$ is an integer because $r$ divides $n+1$. Then
164	\[
165	  \frac1b + \frac1{nb} \;=\; \frac{n+1}{nb} \;=\; \frac{r(n+1)}{n\,r b}
166	  \;=\; \frac{r(n+1)}{n\,a(n+1)} \;=\; \frac{r}{na},
167	\]
168	and \Cref{lem:step} adds $1/a$ to give $4/n$. The divisor here is $u = a$.
169	\end{proof}
170	
171	\begin{theorem}[$r \mid n+4$]
172	\label{thm:np4}
173	If $r \mid n+4$ then $r \mid a+1$, and with $rb = n(a+1)$ and $c = ab$,
174	\[
175	  \frac4n \;=\; \frac1a + \frac1b + \frac1c .
176	\]
177	\end{theorem}
178	
179	\begin{proof}
180	From $4a = n+r$ we get $4(a+1) = (n+4) + r$, so $r \mid 4(a+1)$; as $r$ is odd it
181	is coprime to $4$ and $r \mid a+1$. Hence $b$ is an integer, and
182	\[
183	  \frac1b + \frac1{ab} \;=\; \frac{a+1}{ab} \;=\; \frac{r(a+1)}{a\,rb}
184	  \;=\; \frac{r(a+1)}{a\,n(a+1)} \;=\; \frac{r}{na}.
185	\]
186	The divisor is $u = n$, whose cofactor is $v = na^2$, which is why the third
187	denominator is $a$ times the second.
188	\end{proof}
