2	// Reduced ordered decision graphs with complemented edges. Apply traverses
3	// pairs of graph nodes and interns their reconnections; it never constructs
4	// or tests a prospective numeric factor pair.
5	struct RFrame { unsigned int a,b,v,ah,bh,low,stage; };
6	struct RGraph {
7	    unsigned int *nodes,*unique,*cache,cap,used,error;
8	    unsigned long long steps,limit;
9	    __device__ unsigned int hash(unsigned int a,unsigned int b,unsigned int c) {
10	        unsigned int x=a*0x9e3779b9u ^ b*0x85ebca6bu ^ c*0xc2b2ae35u;
11	        x^=x>>16; x*=0x7feb352du; x^=x>>15; return x;
12	    }
13	    __device__ unsigned int var(unsigned int edge) {
14	        return edge<2?0xffffffffu:nodes[(edge>>1)*3];
15	    }
16	    __device__ unsigned int make(unsigned int v,unsigned int low,unsigned int high) {
17	        if(low==high) return low;
18	        unsigned int flip=high&1u;
19	        low^=flip; high^=flip;
20	        unsigned int slot=hash(v,low,high)&(2*cap-1);
21	        while(unique[slot]) {
22	            unsigned int node=unique[slot];
23	            if(nodes[3*node]==v && nodes[3*node+1]==low && nodes[3*node+2]==high)
24	                return (node<<1)^flip;
25	            slot=(slot+1)&(2*cap-1);
26	        }
27	        if(used>=cap) {error=1;return 0;}
28	        unsigned int node=used++;
29	        nodes[3*node]=v; nodes[3*node+1]=low; nodes[3*node+2]=high;
30	        unique[slot]=node;
31	        return (node<<1)^flip;
32	    }
33	    __device__ unsigned int meet(unsigned int a,unsigned int b) {
34	        RFrame stack[128]; int top=0; unsigned int result=0;
35	        stack[0].a=a;stack[0].b=b;stack[0].stage=0;
36	        while(top>=0 && !error) {
37	            if(++steps>limit) {error=2;break;}
38	            RFrame &f=stack[top];
39	            if(f.stage==0) {
40	                if(f.a>f.b) {unsigned int t=f.a;f.a=f.b;f.b=t;}
41	                if(f.a==0 || f.a==(f.b^1u)) {result=0;--top;continue;}
42	                if(f.a==1 || f.a==f.b) {result=f.b;--top;continue;}
43	                unsigned int slot=(hash(f.a,f.b,0)&(2*cap-1))*3;
44	                if(cache[slot]==f.a && cache[slot+1]==f.b) {result=cache[slot+2];--top;continue;}
45	                unsigned int va=var(f.a),vb=var(f.b);
46	                f.v=va<vb?va:vb;
47	                unsigned int al=f.a,bl=f.b; f.ah=f.a;f.bh=f.b;
48	                if(va==f.v) {al=nodes[(f.a>>1)*3+1]^(f.a&1);f.ah=nodes[(f.a>>1)*3+2]^(f.a&1);}
49	                if(vb==f.v) {bl=nodes[(f.b>>1)*3+1]^(f.b&1);f.bh=nodes[(f.b>>1)*3+2]^(f.b&1);}
50	                f.stage=1;
51	                if(top==127) {error=3;break;}
52	                ++top;stack[top].a=al;stack[top].b=bl;stack[top].stage=0;
53	            } else if(f.stage==1) {
54	                f.low=result;f.stage=2;
55	                unsigned int ah=f.ah,bh=f.bh;
56	                ++top;stack[top].a=ah;stack[top].b=bh;stack[top].stage=0;
57	            } else {
58	                result=make(f.v,f.low,result);
59	                if(error) break;
60	                unsigned int slot=(hash(f.a,f.b,0)&(2*cap-1))*3;
61	                cache[slot]=f.a;cache[slot+1]=f.b;cache[slot+2]=result;
62	                --top;
63	            }
64	        }
65	        return result;
66	    }
