/// effect on the answer.
pub fn bench_search_deep(depth: u32, nest_depth: u32, target: u32, device: usize) -> String {
    let ctx = match CudaContext::new(device) {
        Ok(c) => c, Err(e) => return format!("bench_search_deep: no CUDA: {e}"),
    };
